async function rewardSecret(env){const configured=String(env.REWARDS_AUTH_SECRET||env.D1_AUTH_SECRET||env.GRABZONE_ADMIN_PASSWORD||"").trim();if(configured)return configured;const row=await one(env,"SELECT secret FROM rewards_auth_config WHERE id=1");if(row?.secret)return String(row.secret);const generated=crypto.randomUUID()+crypto.randomUUID()+crypto.randomUUID();const t=now();await env.DB.prepare("INSERT OR IGNORE INTO rewards_auth_config(id,secret,created_at,updated_at) VALUES(1,?,?,?)").bind(generated,t,t).run();const saved=await one(env,"SELECT secret FROM rewards_auth_config WHERE id=1");if(saved?.secret)return String(saved.secret);throw new Error("Rewards authentication secret could not be initialized.")}
