async function rewardAudit(env,memberId,adminId,action,reason,details){await env.DB.prepare("INSERT INTO rewards_audit_log(id,member_id,admin_id,action,reason,details,created_at) VALUES(?,?,?,?,?,?,?)").bind(crypto.randomUUID(),memberId||null,adminId||null,action,reason||null,details?JSON.stringify(details):null,now()).run()}

async function sendTierChangeEmail(env,member,fromTier,toTier,earned,reason=""){
const order={Member:0,Silver:1,Gold:2,Platinum:3};
if(!member||!toTier||fromTier===toTier)return false;
const upgraded=(order[toTier]||0)>(order[fromTier]||0);
const direction=upgraded?"UPGRADE":"DOWNGRADE";
const subject=upgraded?"GrabZone Rewards — Welcome to "+toTier:"GrabZone Rewards — Membership tier update";
const title=upgraded?"You just leveled up.":"Your membership tier changed";
const body=upgraded?"<p>Congratulations! Your Rewards membership moved from <b>"+htmlEsc(fromTier)+"</b> to <b>"+htmlEsc(toTier)+"</b>.</p><p>Your qualifying GrabPoints for the current 12-month window are <b>"+Number(earned||0).toLocaleString("en-BD")+" GP</b>.</p><p>Your new tier benefits and cashback rate are now active.</p>":"<p>Your Rewards membership moved from <b>"+htmlEsc(fromTier)+"</b> to <b>"+htmlEsc(toTier)+"</b>.</p><p>Your current qualifying GrabPoints for the 12-month window are <b>"+Number(earned||0).toLocaleString("en-BD")+" GP</b>.</p><p>Keep earning qualifying GrabPoints to move back up and unlock higher benefits.</p>";
await sendRewardsEmail(env,member.email,subject,title,body+rewardEmailTierCard(toTier),direction,false,toTier,member.name,member.member_id);
return true;
}
async function ensureVendorOrderTables(env){
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS vendor_orders(id TEXT PRIMARY KEY,order_id TEXT NOT NULL,vendor_id TEXT NOT NULL,subtotal REAL NOT NULL DEFAULT 0,shipping_fee REAL NOT NULL DEFAULT 0,commission_amount REAL NOT NULL DEFAULT 0,vendor_earnings REAL NOT NULL DEFAULT 0,delivery_charge REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Processing',created_at TEXT NOT NULL,updated_at TEXT NOT NULL)").run().catch(()=>{});
  await env.DB.prepare("ALTER TABLE vendor_orders ADD COLUMN shipping_fee REAL NOT NULL DEFAULT 0").run().catch(()=>{});
  await env.DB.prepare("ALTER TABLE vendor_orders ADD COLUMN delivery_charge REAL NOT NULL DEFAULT 0").run().catch(()=>{});
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS vendor_order_items(id TEXT PRIMARY KEY,vendor_order_id TEXT NOT NULL,order_item_id TEXT NOT NULL,product_id TEXT,quantity INTEGER NOT NULL DEFAULT 1,unit_price REAL NOT NULL DEFAULT 0,line_total REAL NOT NULL DEFAULT 0,variation_id TEXT,variation_options TEXT,variation_sku TEXT)").run().catch(()=>{});
}
async function routeOrderToVendors(env,orderId,items){
  await ensureVendorOrderTables(env);
  const groups=new Map();
  for(const item of items){
    const p=await q(env,"SELECT p.vendor_id,COALESCE(v.brand_name,v.business_name,v.slug,'GrabZone Vendor') vendor_name,v.email vendor_email,COALESCE(v.shipping_fee,130) shipping_fee,COALESCE(v.commission_type,'percentage') commission_type,COALESCE(v.commission_value,0) commission_value FROM products p LEFT JOIN vendors v ON v.id=p.vendor_id WHERE p.id=? LIMIT 1",[item.product_id]);
    const row=p.results?.[0];
    if(!row?.vendor_id)continue;
    const vid=String(row.vendor_id);
    if(!groups.has(vid))groups.set(vid,{vendor_id:vid,vendor_name:row.vendor_name,vendor_email:row.vendor_email||"",shipping_fee:Number(row.shipping_fee??130),commission_type:String(row.commission_type||'percentage'),commission_value:Number(row.commission_value||0),items:[]});
    groups.get(vid).items.push(item);
  }
  const orderNumber=(await q(env,"SELECT order_number FROM orders WHERE id=? LIMIT 1",[orderId])).results?.[0]?.order_number||orderId;
  const voCols=new Set(((await q(env,"PRAGMA table_info(vendor_orders)")).results||[]).map(x=>x.name));
  const viCols=new Set(((await q(env,"PRAGMA table_info(vendor_order_items)")).results||[]).map(x=>x.name));
  for(const g of groups.values()){
    const existing=await q(env,"SELECT id FROM vendor_orders WHERE order_id=? AND vendor_id=? LIMIT 1",[orderId,g.vendor_id]);
    if(existing.results?.length)continue;
    const subtotal=g.items.reduce((n,x)=>n+Number(x.line_total??Number(x.unit_price||0)*Number(x.quantity||1)),0);
    const commission=g.commission_type==="percentage"?Math.round(subtotal*Math.max(0,g.commission_value)/100*100)/100:Math.min(subtotal,Math.max(0,g.commission_value));
    const vendorShipping=Math.max(0,Number(g.shipping_fee??130));
    const vo={id:crypto.randomUUID(),order_id:orderId,vendor_id:g.vendor_id,subtotal,commission_amount:commission,vendor_earnings:Math.max(0,subtotal-commission),shipping_fee:vendorShipping,delivery_charge:vendorShipping,status:"Processing",created_at:now(),updated_at:now()};
    const fields=Object.keys(vo).filter(k=>voCols.has(k));
    if(!fields.includes("id")||!fields.includes("order_id")||!fields.includes("vendor_id"))continue;
    await env.DB.prepare("INSERT INTO vendor_orders("+fields.join(",")+") VALUES("+fields.map(()=>"?").join(",")+")").bind(...fields.map(k=>vo[k])).run();
    for(const item of g.items){
      const vi={id:crypto.randomUUID(),vendor_order_id:vo.id,order_item_id:item.id,product_id:item.product_id,quantity:Number(item.quantity||1),unit_price:Number(item.unit_price||0),line_total:Number(item.line_total??Number(item.unit_price||0)*Number(item.quantity||1)),variation_id:item.variation_id||null,variation_options:item.variation_options?JSON.stringify(item.variation_options):null,variation_sku:item.variation_sku||item.sku||null};
      const fields2=Object.keys(vi).filter(k=>viCols.has(k));
      if(!fields2.includes("id")||!fields2.includes("vendor_order_id")||!fields2.includes("order_item_id"))continue;
      await env.DB.prepare("INSERT INTO vendor_order_items("+fields2.join(",")+") VALUES("+fields2.map(()=>"?").join(",")+")").bind(...fields2.map(k=>vi[k])).run();
    }
    await sendVendorOrderEmail(env,{to:g.vendor_email,vendorName:g.vendor_name,orderNumber,items:g.items,subtotal});
  }
}
