 if(!env.ASSETS_BUCKET)return json({error:"Photo storage is not configured."},500);
 const ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"")||"jpg",key="grabzone/reviews/"+new Date().toISOString().slice(0,10)+"/"+crypto.randomUUID()+"."+ext;
