 await env.DB.prepare("INSERT INTO product_reviews(id,product_id,customer_name,rating,review_text,photo_url,approved,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)").bind(id,productId,name,rating,text,photo,0,t,t).run();
