async function productReviews(req,env){
 await ensureSchema(env);
 const u=new URL(req.url);
 if(req.method==="GET"){
  const id=String(u.searchParams.get("product_id")||"").trim();
  const admin=u.searchParams.get("admin")==="1";
  if(admin&&!await session(req,env))return json({error:"Unauthorized."},401);
  const where=id?" WHERE product_id=?"+(admin?"":" AND approved=1"):(admin?"":" WHERE approved=1");
  const params=id?[id]:[];
  const rows=(await q(env,"SELECT id,product_id,customer_name,rating,review_text,photo_url,approved,created_at,updated_at FROM product_reviews"+where+" ORDER BY created_at DESC LIMIT 500",params)).results||[];
  return json({reviews:rows});
 }
 if(req.method==="POST"){
  let b={};try{b=await req.json()}catch{return json({error:"Invalid JSON."},400)}
  const id=String(b.product_id||"").trim(),name=String(b.customer_name||"").trim(),text=String(b.review_text||"").trim(),rating=Math.floor(Number(b.rating));
  if(!id||!name||!text)return json({error:"Product, customer name and review are required."},400);
  if(name.length>80)return json({error:"Customer name is too long."},400);
  if(text.length>1000)return json({error:"Review is too long."},400);
  if(!Number.isInteger(rating)||rating<1||rating>5)return json({error:"Rating must be between 1 and 5."},400);
  const p=(await q(env,"SELECT id FROM products WHERE id=? AND published=1 LIMIT 1",[id])).results?.[0];
  if(!p)return json({error:"Product is not available."},404);
  const t=now(),rid=crypto.randomUUID();
  await env.DB.prepare("INSERT INTO product_reviews(id,product_id,customer_name,rating,review_text,approved,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)").bind(rid,id,name,rating,text,0,t,t).run();
  return json({ok:true,id:rid,approved:false});
 }
 if(!await session(req,env))return json({error:"Unauthorized."},401);
 if(req.method==="PATCH"||req.method==="PUT"){
  let b={};try{b=await req.json()}catch{return json({error:"Invalid JSON."},400)}
  const id=String(b.id||"").trim();
  if(!id)return json({error:"Review ID is required."},400);
  const approved=b.approved===true||b.approved===1||b.approved==="1";
  await env.DB.prepare("UPDATE product_reviews SET approved=?,updated_at=? WHERE id=?").bind(approved?1:0,now(),id).run();
  return json({ok:true});
 }
 if(req.method==="DELETE"){
  const id=String(u.searchParams.get("id")||"").trim();
  if(!id)return json({error:"Review ID is required."},400);
  await env.DB.prepare("DELETE FROM product_reviews WHERE id=?").bind(id).run();
  return json({ok:true});
 }
 return json({error:"Method not allowed."},405);
}
