async function shippingSettings(req,env){
  await ensureShippingSetting(env);
  if(req.method==="GET")return json({ok:true,global_shipping_fee:await getGlobalShipping(env)});
  if(req.method!=="PATCH")return json({error:"Method not allowed."},405);
  const s=await session(req,env);if(!s)return json({error:"Unauthorized."},401);
  const b=await req.json().catch(()=>({})),fee=Number(b.global_shipping_fee);
  if(!Number.isFinite(fee)||fee<0||fee>100000)return json({error:"Enter a valid shipping fee."},400);
  await env.DB.prepare("UPDATE site_settings SET global_shipping_fee=?,updated_at=? WHERE id=1").bind(fee,now()).run();
  return json({ok:true,global_shipping_fee:fee});
}
